macro_rules! deps {
    () => {
        PointerMetadata!();
    };
}

macro_rules! KnownLayout {
    () => {
        deps!();
        # [doc = " Indicates that zerocopy can reason about certain aspects of a type's layout."] # [doc = ""] # [doc = " This trait is required by many of zerocopy's APIs. It supports sized types,"] # [doc = " slices, and [slice DSTs](#dynamically-sized-types)."] # [doc = ""] # [doc = " # Implementation"] # [doc = ""] # [doc = " **Do not implement this trait yourself!** Instead, use"] # [doc = " [`#[derive(KnownLayout)]`][derive]; e.g.:"] # [doc = ""] # [doc = " ```"] # [doc = " # use zerocopy_derive::KnownLayout;"] # [doc = " #[derive(KnownLayout)]"] # [doc = " struct MyStruct {"] # [doc = " # /*"] # [doc = "     ..."] # [doc = " # */"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(KnownLayout)]"] # [doc = " enum MyEnum {"] # [doc = " # /*"] # [doc = "     ..."] # [doc = " # */"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(KnownLayout)]"] # [doc = " union MyUnion {"] # [doc = " #   variant: u8,"] # [doc = " # /*"] # [doc = "     ..."] # [doc = " # */"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This derive performs a sophisticated analysis to deduce the layout"] # [doc = " characteristics of types. You **must** implement this trait via the derive."] # [doc = ""] # [doc = " # Dynamically-sized types"] # [doc = ""] # [doc = " `KnownLayout` supports slice-based dynamically sized types (\"slice DSTs\")."] # [doc = ""] # [doc = " A slice DST is a type whose trailing field is either a slice or another"] # [doc = " slice DST, rather than a type with fixed size. For example:"] # [doc = ""] # [doc = " ```"] # [doc = " #[repr(C)]"] # [doc = " struct PacketHeader {"] # [doc = " # /*"] # [doc = "     ..."] # [doc = " # */"] # [doc = " }"] # [doc = ""] # [doc = " #[repr(C)]"] # [doc = " struct Packet {"] # [doc = "     header: PacketHeader,"] # [doc = "     body: [u8],"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " It can be useful to think of slice DSTs as a generalization of slices - in"] # [doc = " other words, a normal slice is just the special case of a slice DST with"] # [doc = " zero leading fields. In particular:"] # [doc = " - Like slices, slice DSTs can have different lengths at runtime"] # [doc = " - Like slices, slice DSTs cannot be passed by-value, but only by reference"] # [doc = "   or via other indirection such as `Box`"] # [doc = " - Like slices, a reference (or `Box`, or other pointer type) to a slice DST"] # [doc = "   encodes the number of elements in the trailing slice field"] # [doc = ""] # [doc = " ## Slice DST layout"] # [doc = ""] # [doc = " Just like other composite Rust types, the layout of a slice DST is not"] # [doc = " well-defined unless it is specified using an explicit `#[repr(...)]`"] # [doc = " attribute such as `#[repr(C)]`. [Other representations are"] # [doc = " supported][reprs], but in this section, we'll use `#[repr(C)]` as our"] # [doc = " example."] # [doc = ""] # [doc = " A `#[repr(C)]` slice DST is laid out [just like sized `#[repr(C)]`"] # [doc = " types][repr-c-structs], but the presence of a variable-length field"] # [doc = " introduces the possibility of *dynamic padding*. In particular, it may be"] # [doc = " necessary to add trailing padding *after* the trailing slice field in order"] # [doc = " to satisfy the outer type's alignment, and the amount of padding required"] # [doc = " may be a function of the length of the trailing slice field. This is just a"] # [doc = " natural consequence of the normal `#[repr(C)]` rules applied to slice DSTs,"] # [doc = " but it can result in surprising behavior. For example, consider the"] # [doc = " following type:"] # [doc = ""] # [doc = " ```"] # [doc = " #[repr(C)]"] # [doc = " struct Foo {"] # [doc = "     a: u32,"] # [doc = "     b: u8,"] # [doc = "     z: [u16],"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Assuming that `u32` has alignment 4 (this is not true on all platforms),"] # [doc = " then `Foo` has alignment 4 as well. Here is the smallest possible value for"] # [doc = " `Foo`:"] # [doc = ""] # [doc = " ```text"] # [doc = " byte offset | 01234567"] # [doc = "       field | aaaab---"] # [doc = "                    ><"] # [doc = " ```"] # [doc = ""] # [doc = " In this value, `z` has length 0. Abiding by `#[repr(C)]`, the lowest offset"] # [doc = " that we can place `z` at is 5, but since `z` has alignment 2, we need to"] # [doc = " round up to offset 6. This means that there is one byte of padding between"] # [doc = " `b` and `z`, then 0 bytes of `z` itself (denoted `><` in this diagram), and"] # [doc = " then two bytes of padding after `z` in order to satisfy the overall"] # [doc = " alignment of `Foo`. The size of this instance is 8 bytes."] # [doc = ""] # [doc = " What about if `z` has length 1?"] # [doc = ""] # [doc = " ```text"] # [doc = " byte offset | 01234567"] # [doc = "       field | aaaab-zz"] # [doc = " ```"] # [doc = ""] # [doc = " In this instance, `z` has length 1, and thus takes up 2 bytes. That means"] # [doc = " that we no longer need padding after `z` in order to satisfy `Foo`'s"] # [doc = " alignment. We've now seen two different values of `Foo` with two different"] # [doc = " lengths of `z`, but they both have the same size - 8 bytes."] # [doc = ""] # [doc = " What about if `z` has length 2?"] # [doc = ""] # [doc = " ```text"] # [doc = " byte offset | 012345678901"] # [doc = "       field | aaaab-zzzz--"] # [doc = " ```"] # [doc = ""] # [doc = " Now `z` has length 2, and thus takes up 4 bytes. This brings our un-padded"] # [doc = " size to 10, and so we now need another 2 bytes of padding after `z` to"] # [doc = " satisfy `Foo`'s alignment."] # [doc = ""] # [doc = " Again, all of this is just a logical consequence of the `#[repr(C)]` rules"] # [doc = " applied to slice DSTs, but it can be surprising that the amount of trailing"] # [doc = " padding becomes a function of the trailing slice field's length, and thus"] # [doc = " can only be computed at runtime."] # [doc = ""] # [doc = " [reprs]: https://doc.rust-lang.org/reference/type-layout.html#representations"] # [doc = " [repr-c-structs]: https://doc.rust-lang.org/reference/type-layout.html#reprc-structs"] # [doc = ""] # [doc = " ## What is a valid size?"] # [doc = ""] # [doc = " There are two places in zerocopy's API that we refer to \"a valid size\" of a"] # [doc = " type. In normal casts or conversions, where the source is a byte slice, we"] # [doc = " need to know whether the source byte slice is a valid size of the"] # [doc = " destination type. In prefix or suffix casts, we need to know whether *there"] # [doc = " exists* a valid size of the destination type which fits in the source byte"] # [doc = " slice and, if so, what the largest such size is."] # [doc = ""] # [doc = " As outlined above, a slice DST's size is defined by the number of elements"] # [doc = " in its trailing slice field. However, there is not necessarily a 1-to-1"] # [doc = " mapping between trailing slice field length and overall size. As we saw in"] # [doc = " the previous section with the type `Foo`, instances with both 0 and 1"] # [doc = " elements in the trailing `z` field result in a `Foo` whose size is 8 bytes."] # [doc = ""] # [doc = " When we say \"x is a valid size of `T`\", we mean one of two things:"] # [doc = " - If `T: Sized`, then we mean that `x == size_of::<T>()`"] # [doc = " - If `T` is a slice DST, then we mean that there exists a `len` such that the instance of"] # [doc = "   `T` with `len` trailing slice elements has size `x`"] # [doc = ""] # [doc = " When we say \"largest possible size of `T` that fits in a byte slice\", we"] # [doc = " mean one of two things:"] # [doc = " - If `T: Sized`, then we mean `size_of::<T>()` if the byte slice is at least"] # [doc = "   `size_of::<T>()` bytes long"] # [doc = " - If `T` is a slice DST, then we mean to consider all values, `len`, such"] # [doc = "   that the instance of `T` with `len` trailing slice elements fits in the"] # [doc = "   byte slice, and to choose the largest such `len`, if any"] # [doc = ""] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This trait does not convey any safety guarantees to code outside this crate."] # [doc = ""] # [doc = " You must not rely on the `#[doc(hidden)]` internals of `KnownLayout`. Future"] # [doc = " releases of zerocopy may make backwards-breaking changes to these items,"] # [doc = " including changes that only affect soundness, which may cause code which"] # [doc = " uses those items to silently become unsound."] # [doc = ""] # [cfg_attr (feature = "derive" , doc = "[derive]: zerocopy_derive::KnownLayout")] # [cfg_attr (not (feature = "derive") , doc = concat ! ("[derive]: https://docs.rs/zerocopy/" , env ! ("CARGO_PKG_VERSION") , "/zerocopy/derive.KnownLayout.html") ,)] # [cfg_attr (zerocopy_diagnostic_on_unimplemented_1_78_0 , diagnostic :: on_unimplemented (note = "Consider adding `#[derive(KnownLayout)]` to `{Self}`"))] pub unsafe trait KnownLayout { # [doc (hidden)] fn only_derive_is_allowed_to_implement_this_trait () where Self : Sized ; # [doc = " The type of metadata stored in a pointer to `Self`."] # [doc = ""] # [doc = " This is `()` for sized types and `usize` for slice DSTs."] type PointerMetadata : PointerMetadata ; # [doc = " A maybe-uninitialized analog of `Self`"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " `Self::LAYOUT` and `Self::MaybeUninit::LAYOUT` are identical."] # [doc = " `Self::MaybeUninit` admits uninitialized bytes in all positions."] # [doc (hidden)] type MaybeUninit : ? Sized + KnownLayout < PointerMetadata = Self :: PointerMetadata > ; # [doc = " The layout of `Self`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Callers may assume that `LAYOUT` accurately reflects the layout of"] # [doc = " `Self`. In particular:"] # [doc = " - `LAYOUT.align` is equal to `Self`'s alignment"] # [doc = " - If `Self: Sized`, then `LAYOUT.size_info == SizeInfo::Sized { size }`"] # [doc = "   where `size == size_of::<Self>()`"] # [doc = " - If `Self` is a slice DST, then `LAYOUT.size_info =="] # [doc = "   SizeInfo::SliceDst(slice_layout)` where:"] # [doc = "   - The size, `size`, of an instance of `Self` with `elems` trailing"] # [doc = "     slice elements is equal to `slice_layout.offset +"] # [doc = "     slice_layout.elem_size * elems` rounded up to the nearest multiple"] # [doc = "     of `LAYOUT.align`"] # [doc = "   - For such an instance, any bytes in the range `[slice_layout.offset +"] # [doc = "     slice_layout.elem_size * elems, size)` are padding and must not be"] # [doc = "     assumed to be initialized"] # [doc (hidden)] const LAYOUT : DstLayout ; # [doc = " SAFETY: The returned pointer has the same address and provenance as"] # [doc = " `bytes`. If `Self` is a DST, the returned pointer's referent has `elems`"] # [doc = " elements in its trailing slice."] # [doc (hidden)] fn raw_from_ptr_len (bytes : NonNull < u8 > , meta : Self :: PointerMetadata) -> NonNull < Self > ; # [doc = " Extracts the metadata from a pointer to `Self`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " `pointer_to_metadata` always returns the correct metadata stored in"] # [doc = " `ptr`."] # [doc (hidden)] fn pointer_to_metadata (ptr : * mut Self) -> Self :: PointerMetadata ; # [doc = " Computes the length of the byte range addressed by `ptr`."] # [doc = ""] # [doc = " Returns `None` if the resulting length would not fit in an `usize`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Callers may assume that `size_of_val_raw` always returns the correct"] # [doc = " size."] # [doc = ""] # [doc = " Callers may assume that, if `ptr` addresses a byte range whose length"] # [doc = " fits in an `usize`, this will return `Some`."] # [doc (hidden)] # [must_use] # [inline (always)] fn size_of_val_raw (ptr : NonNull < Self >) -> Option < usize > { let meta = Self :: pointer_to_metadata (ptr . as_ptr ()) ; Self :: size_for_metadata (meta) } # [doc (hidden)] # [must_use] # [inline (always)] fn raw_dangling () -> NonNull < Self > { let meta = Self :: PointerMetadata :: from_elem_count (0) ; Self :: raw_from_ptr_len (NonNull :: dangling () , meta) } # [doc = " Computes the size of an object of type `Self` with the given pointer"] # [doc = " metadata."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " `size_for_metadata` promises to return `None` if and only if the"] # [doc = " resulting size would not fit in a `usize`. Note that the returned size"] # [doc = " could exceed the actual maximum valid size of an allocated object,"] # [doc = " `isize::MAX`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use zerocopy::KnownLayout;"] # [doc = ""] # [doc = " assert_eq!(u8::size_for_metadata(()), Some(1));"] # [doc = " assert_eq!(u16::size_for_metadata(()), Some(2));"] # [doc = " assert_eq!(<[u8]>::size_for_metadata(42), Some(42));"] # [doc = " assert_eq!(<[u16]>::size_for_metadata(42), Some(84));"] # [doc = ""] # [doc = " // This size exceeds the maximum valid object size (`isize::MAX`):"] # [doc = " assert_eq!(<[u8]>::size_for_metadata(usize::MAX), Some(usize::MAX));"] # [doc = ""] # [doc = " // This size, if computed, would exceed `usize::MAX`:"] # [doc = " assert_eq!(<[u16]>::size_for_metadata(usize::MAX), None);"] # [doc = " ```"] # [inline (always)] fn size_for_metadata (meta : Self :: PointerMetadata) -> Option < usize > { meta . size_for_metadata (Self :: LAYOUT) } }
    };
}

KnownLayout!()